def merge_intervals(intervals):
    """Merge overlapping (start, end) intervals into disjoint ranges.

    Intervals with reversed bounds (start > end) are rejected.
    """
    if not intervals:
        return []

    normalized = []
    for pair in intervals:
        if len(pair) != 2:
            raise ValueError("Each interval must contain exactly two values: (start, end).")
        start, end = pair
        if start > end:
            raise ValueError(f"Invalid interval with reversed bounds: ({start}, {end})")
        normalized.append((start, end))

    normalized.sort(key=lambda p: (p[0], p[1]))

    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged
```

