def split_cents(total, n):
    """Split a cent total into n integer parts whose sum is exactly total.

    For non-divisible totals, earlier parts get the extra cent(s).
    Negative totals mirror the positive split (element-wise negation).
    """
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError("total must be an integer number of cents")
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n <= 0:
        raise ValueError("n must be a positive integer")

    if total < 0:
        return [-x for x in split_cents(-total, n)]

    part, remainder = divmod(total, n)
    return [part + 1] * remainder + [part] * (n - remainder)
```

